use moro_ai_bridge::provider::parse_output;
use serde_json::{json,Value};
const WARNING:&str="Code Mode is unavailable because code-mode host is disabled. Code mode will fail closed; enable `features.code_mode_host` and install `codex-code-mode-host`.";
fn project()->Value{json!({"version":1,"name":"Test","width":512,"height":512,"fps":60,"durationFrames":120,"layers":[]})}
fn stream(extra:Option<Value>)->Vec<u8>{let mut lines=vec![json!({"type":"thread.started"}),json!({"type":"turn.started"})];if let Some(v)=extra{lines.push(v);}lines.push(json!({"type":"item.completed","item":{"type":"agent_message","text":project().to_string()}}));lines.push(json!({"type":"turn.completed"}));lines.iter().map(Value::to_string).collect::<Vec<_>>().join("\n").into_bytes()}
#[test]fn exact_disabled_host_warning_is_safe_only_with_explicit_disabled_host(){let out=stream(Some(json!({"type":"item.completed","item":{"type":"error","message":WARNING}})));assert!(moro_ai_bridge::provider::parse_output_for_invocation("codex",&out,true).is_ok(),"exact contract-approved fail-closed diagnostic must not prevent a valid proposal");assert!(parse_output("codex",&out).is_err(),"without explicit host-disable evidence warning remains an error");}
#[test]fn reject_tools_file_changes_errors_unknown_events_and_bad_projects(){for item in ["command_execution","mcp_tool_call","web_search","file_change","image_generation","error","unknown"]{let out=stream(Some(json!({"type":"item.completed","item":{"type":item,"message":"NO"}})));assert!(parse_output("codex",&out).is_err(),"{item}");}let out=stream(Some(json!({"type":"error","message":"anything"})));assert!(parse_output("codex",&out).is_err());}
#[test]fn disabled_host_warning_exception_never_accepts_changed_extra_or_tool_events(){
 use moro_ai_bridge::provider::parse_output_for_invocation as parse;
 for message in [format!("{WARNING} extra"),WARNING.replace("will fail closed","Falling back to direct tools"),WARNING.trim_end_matches('.').to_string()] {assert!(parse("codex",&stream(Some(json!({"type":"item.completed","item":{"type":"error","message":message}}))),true).is_err());}
 let warning=json!({"type":"item.completed","item":{"type":"error","message":WARNING}}).to_string();
 for extra in [json!({"type":"item.completed","item":{"type":"error","message":"other"}}),json!({"type":"item.completed","item":{"type":"file_change"}}),json!({"type":"item.completed","item":{"type":"command_execution"}}),json!({"type":"item.completed","item":{"type":"error","message":WARNING}})] {let mut out=stream(Some(extra));out.extend_from_slice(format!("\n{warning}").as_bytes());assert!(parse("codex",&out,true).is_err());}
 let out=format!("{warning}\n{}",json!({"type":"turn.completed"}));assert!(parse("codex",out.as_bytes(),true).is_err());
}
#[test]fn disabled_host_warning_is_a_startup_diagnostic_not_a_trailing_error(){let mut out=stream(None);out.extend_from_slice(format!("\n{}",json!({"type":"item.completed","item":{"type":"error","message":WARNING}})).as_bytes());assert!(moro_ai_bridge::provider::parse_output_for_invocation("codex",&out,true).is_err());}
#[test]fn real_claude_success_subtype_with_invalid_oauth_is_never_success(){let out=json!({"type":"result","subtype":"success","is_error":true,"stop_reason":"stop_sequence","result":"Failed to authenticate...401 OAuth access token is invalid.","permission_denials":[]});assert_eq!(parse_output("claude",out.to_string().as_bytes()).unwrap_err(),"needs_login");}
#[test]fn claude_accepts_only_explicit_success_and_structured_output(){let v=json!({"type":"result","subtype":"success","is_error":false,"structured_output":project(),"permission_denials":[]});assert!(parse_output("claude",v.to_string().as_bytes()).is_ok());for key in ["is_error","structured_output","permission_denials"]{let mut bad=v.clone();bad.as_object_mut().unwrap().remove(key);assert!(parse_output("claude",bad.to_string().as_bytes()).is_err());}}
